"""Wording trims to reach six pages (applied before cut.py, so citation numbers are still the old ones)."""
import sys, re, docx
src, out = sys.argv[1], sys.argv[2]
d = docx.Document(src)
def find(start):
    for p in d.paragraphs:
        if p.text.startswith(start): return p
    raise SystemExit("missing " + start)
def merge(p):
    rs = p.runs; rs[0].text = p.text
    for r in rs[1:]: r._r.getparent().remove(r._r)
def edit(start, *pairs, whole=None):
    p = find(start); merge(p); t = p.runs[0].text
    if whole is not None: t = whole
    for a, b in pairs:
        assert a in t, (start, a); t = t.replace(a, b)
    p.runs[0].text = re.sub(r" {2,}", " ", t)
