# merge E into D, relabel subsection letters
E = find("E. Temporal Subgraph Anomaly Scoring"); Etxt = E._p.getnext()
D = find("A two-layer graph"); merge(D)
D.runs[0].text = D.runs[0].text.rstrip() + " The anomaly score of a step is the distance between the predicted and the actual vector (Eq. (13)), and the patient score is the maximum over the 20 regions and all steps (Eq. (14))."
E._p.getparent().remove(Etxt); E._p.getparent().remove(E._p)
on = False; letter = iter("ABCDEFGHIJKL")
for p in d.paragraphs:
    if p.text.startswith("III. METHODOLOGY"): on = True; continue
    if p.text.startswith("IV. RESULTS"): break
    if on and re.match(r"^[A-L]\. ", p.text) and len(p.text) < 80:
        new = next(letter)
        for r in p.runs:
            if re.match(r"^[A-L]\. ", r.text): r.text = new + r.text[1:]; break
d.save(out)
